erection.validator:
function valid(record,day){
 const lesson=lessonOf(day);
 if(!record||Array.isArray(record)||!lesson||record.erectionPracticeVersion!==1||record.day!==Number(day)||record.confirmed!==true||!score(record.anxiety)||!score(record.confidence))return false;
 // Día 1 conserva el registro histórico EHS. Los días reubicados exigen el
 // identificador de sesión para no atribuirles resultados de otras prácticas.
 if(lesson===1){
  if(record.erectionLesson!=null&&record.erectionLesson!==1)return false;
  const omitted=record.ehsStatus==='omitted'&&record.ehsOmitted===true&&record.ehs===null&&record.ehsEvaluable===null;
  const notEvaluable=record.ehs===null&&record.ehsEvaluable===false&&record.ehsOmitted!==true&&(record.ehsStatus==null||record.ehsStatus==='not_evaluable');
  const measured=Number.isInteger(record.ehs)&&record.ehs>=0&&record.ehs<=4&&record.ehsEvaluable===true&&record.ehsOmitted!==true&&(record.ehsStatus==null||record.ehsStatus==='recorded');
  if(!omitted&&!notEvaluable&&!measured)return false;
  // Los registros históricos siguen siendo legibles. La versión con salida
  // voluntaria valida por separado la conclusión y la realización física.
  if(record.completionAccepted===true||record.ehsStatus!=null){
   if(record.completionAccepted!==true||!['maintained','returned','difficult','omitted'].includes(record.attentionPracticeOutcome))return false;
   const practiced=record.attentionPracticeOutcome!=='omitted';
   return record.attentionPracticeCompleted===practiced&&record.completed===practiced&&record.activityStatus===(practiced?'completed':'omitted');
  }
  return true;
 }
 if(record.erectionLesson!==lesson)return false;
 if(lesson===2)return !!record.contexts&&contexts.every(key=>contextValues.includes(record.contexts[key]))&&aspects.includes(record.responseAspect);
 if(lesson===3)return Array.isArray(record.tensionAreas)&&record.tensionAreas.length>0&&new Set(record.tensionAreas).size===record.tensionAreas.length&&record.tensionAreas.every(area=>areas.includes(area))&&(!record.tensionAreas.includes('none')||record.tensionAreas.length===1)&&anchors.includes(record.sensoryAnchor)&&reflection(record);
 if(lesson===4)return senses.includes(record.attentionSense)&&experiences.includes(record.practiceExperience)&&reflection(record);
  if(lesson===5)return selection(record.erectionFacilitators,facilitators,3)&&selection(record.erectionInhibitors,inhibitors,2)&&adjustments.includes(record.microAdjustment);
 if(lesson===6)return Array.isArray(record.erectionStimuli)&&record.erectionStimuli.length>=1&&record.erectionStimuli.length<=6&&new Set(record.erectionStimuli).size===record.erectionStimuli.length&&record.erectionStimuli.every(value=>stimuli.includes(value));
 if(lesson===7)return Array.isArray(record.erectionProgress)&&record.erectionProgress.length>=1&&record.erectionProgress.length<=4&&new Set(record.erectionProgress).size===record.erectionProgress.length&&record.erectionProgress.every(value=>progressMarkers.includes(value))&&(!record.erectionProgress.includes('empezando')||record.erectionProgress.length===1)&&confidenceIdeas.includes(record.erectionConfidenceStatement)&&nextSteps.includes(record.erectionNextStep);
 if(lesson===8)return Array.isArray(record.erectionFavorablePositions)&&record.erectionFavorablePositions.length>=1&&record.erectionFavorablePositions.length<=6&&new Set(record.erectionFavorablePositions).size===record.erectionFavorablePositions.length&&record.erectionFavorablePositions.every(value=>positions.includes(value)||value==='no_evaluable')&&(!record.erectionFavorablePositions.includes('no_evaluable')||record.erectionFavorablePositions.length===1)&&(record.erectionLessFavorablePosition==null||record.erectionLessFavorablePosition==='no_identificada'||positions.includes(record.erectionLessFavorablePosition))&&positionStrategies.includes(record.erectionChosenStrategy)&&(record.erectionPracticeStarted==null||typeof record.erectionPracticeStarted==='boolean')&&(record.erectionOptionalTimerSeconds==null||Number.isSafeInteger(record.erectionOptionalTimerSeconds)&&record.erectionOptionalTimerSeconds>=0);
 if(lesson===9)return responseStrategies.includes(record.erectionResponseStrategy)&&Array.isArray(record.erectionPlanStepsHeard)&&record.erectionPlanStepsHeard.length<=4&&new Set(record.erectionPlanStepsHeard).size===record.erectionPlanStepsHeard.length&&record.erectionPlanStepsHeard.every(n=>Number.isInteger(n)&&n>=0&&n<=3);
 if(lesson===10)return Array.isArray(record.warningSignals)&&record.warningSignals.length>=1&&record.warningSignals.length<=4&&new Set(record.warningSignals).size===record.warningSignals.length&&record.warningSignals.every(v=>preventionSignals.includes(v))&&(!record.warningSignals.includes('none')||record.warningSignals.length===1)&&preventionStrategies.includes(record.preventionStrategy);
 return false;
}
